T8U	bCommType;INT8U	bXorChkTemp;INT8U	bXorChk;INT8U	bIndex;INT32U	dwFlashAddr;INT32U	dwFlashAddrP;INT32U	dwFlashAddrOffset;INT64U	wFlashData;INT32U	wFlashData1;INT32U	wFlashData2;INT16U	uwFlashDataLen = 0;INT8U	bAddId1;INT8U	bAddId2;INT8U	bAddChar1;INT8U	bAddChar2;INT8U	bTxDelay;INT8U	bResDelay;INT16U	wKeyPressCnt;INT16U	wKeyStatusCnt;INT16U	wKeyPressCnt;INT16U	wKeyStatusCnt;INT32U	dwIAPCRCData = 0;		// 上位机下来的CRC值INT32U	dwFlashCRCData = 0;extern INT16U wakeCount;INT16U   BootFlag[8] = {0XFFFF,0XFFFF,0X4635,0X504E,0XFFFF,0XFFFF,0XFFFF,0XFFFF};#pragma  DATA_SECTION(BootData,"BufferDataSection");uint16   BootData[cRX_BUFF_LEN_MAX];uint32   *BootData32 = (uint32 *)BootData;void	IAP_ShutDownChk(void);static INT32U sdwFlashCrc32(const INT16U *buf, INT32U size);/********************************************************************************* FLASH																		*********************************************************************************//********************************************************************************* BOOT Updater																	*********************************************************************************/void	sIapFlgLook(void){	INT8U *pIAPFlagH;	INT8U *pIAPFlagL;	INT8U *pAppBeginCmd;	pIAPFlagH = (INT8U *)FLASH_APP_BOOT_ADDR;	pIAPFlagL = (INT8U *)(FLASH_APP_BOOT_ADDR + 1);	pAppBeginCmd = (INT8U *)FLASH_APP_ADDR_START;		if(*pAppBeginCmd != 0XFFFF)	// APP启动跳转指令空间不为空	{		if((*pIAPFlagH == 0X4635) && (*pIAPFlagL == 0X504E))		{			asm("   LB  0x84000");	// go to App		}	}}void	IAP_Updater(void){	IAP_Initial();				// IAP初始化	IAP_WaitPing();				// ping帧				bWatchDog = 1;	sIWDG_SysCtl_serviceWatchdog();		IAP_BootFlagErase();		// boot标志擦除	IAP_AppFlashErase();		// app标志擦除	IAP_AppFlashProgram();		// IAP升级程序	}void	IAP_Initial(void){	dwUartRegs = BOOT_SCI_A;	bCommType = 0;	bWatchDog = 0;		bRxIndex = 0;		for(bIndex = 0; bIndex < cRX_BUFF_LEN_MAX; bIndex++)	{		BootData[bIndex] = 0xFFFF;	// 对于flash，0XFFFF是默认值		bRxBuff[bIndex] = 0;			}	bIndex = 0;		bTxDelay  = 5;	bResDelay = 5;		bXorChkTemp = 0;	bXorChk = 0xFF;	dwFlashAddr = 0;	dwFlashAddrOffset = FLASH_IAP_ADDR_START;	wFlashData = 0xFFFF;	dwFlashAddrP = FLASH_APP_ADDR_START;}void	IAP_WaitPing(void){	while(1)	{		IAP_UartRecv();				if(bRxBuff[bRxIndex] == '\r')		{			if((bRxBuff[0] == 'F') && (bRxBuff[1] == '5') \				&& (bRxBuff[2] == 'P') && (bRxBuff[3] == 'N') \				&& (bRxBuff[6] == '\r'))			{								if((bRxBuff[4]=='0' && bRxBuff[5]=='1'))				{					IAP_DelayMs(bTxDelay);					IAP_UartSend('A');					IAP_UartSend('\r');					IAP_DelayMs(bResDelay);					break;				}				else				{					bRxIndex = 0;				}			}			else			{				bRxIndex = 0;			}			bRxBuff[0] = 0;		}		else if((bRxIndex < (cRX_BUFF_LEN_MAX - 1)) && (bCommType != 0))		{			bRxIndex++;		}	}}INT32U	IAP_BootFlagCheck(void)				// 检查启动标志{//	// Check Boot Flag 						-- 检查启动标志//	if((*(__IO INT32U*)FLASH_IAP_FLG_ADDR) != cFLASH_IAP_FLG_VALUE)//	{//		// Boot is damaged, update was needed or requested. -- 启动损坏，需要或请求更新。//		return 1;//	}	//	//	// Boot is OK, No update was needed or requested.       -- 启动正常，不需要或请求任何更新。	return 0;}void	IAP_BootFlagErase(void)				// boot标志擦除{    Fapi_StatusType  oReturnCheck;    Fapi_FlashStatusWordType  oFlashStatusWord;	// Bzero_Sector8_start   ????????    oReturnCheck = Fapi_issueAsyncCommandWithAddress(Fapi_EraseSector,(uint32 *)FLASH_APP_ADDR_BEGIN);    while(Fapi_checkFsmForReady() != Fapi_Status_FsmReady){}    oReturnCheck = Fapi_doBlankCheck((uint32 *)FLASH_APP_ADDR_BEGIN, Sector2KB_u32length,&oFlashStatusWord);    if(oReturnCheck != Fapi_Status_Success)    {        Example_Error(oReturnCheck);    }}void	IAP_AppFlashErase(void)				// app标志与APP段数据擦除{	INT32U	address;	Fapi_StatusType  oReturnCheck;    Fapi_FlashStatusWordType  oFlashStatusWord;        //    //Give pump ownership to FMC0    //    PUMPREQUEST = 0x5A5A0002;    //    // This function is required to initialize the Flash API based on System    // frequency before any other Flash API operation can be performed    // Note that the FMC0 register base address is passed as the parameter    //    oReturnCheck = Fapi_initializeAPI(F021_CPU0_W0_BASE_ADDRESS, 200);    if(oReturnCheck != Fapi_Status_Success)    {        //        // Check Flash API documentation for possible errors        //        Example_Error(oReturnCheck);    }    //    // Fapi_setActiveFlashBank function sets the Flash bank0 and FMC0 for    // further Flash operations to be performed on the bank0.    // Note that the parameter passed is Fapi_FlashBank0 since FMC0 register    // base address is passed to Fapi_initializeAPI()    //    oReturnCheck = Fapi_setActiveFlashBank(Fapi_FlashBank0);    if(oReturnCheck != Fapi_Status_Success)    {        //        // Check Flash API documentation for possible errors        //        Example_Error(oReturnCheck);    }	for(address = FLASH_APP_ADDR_BEGIN; address < FLASH_APP_ADDR_END; address += 0x400)	{		    oReturnCheck = Fapi_issueAsyncCommandWithAddress(Fapi_EraseSector,(uint32 *)address);	    while(Fapi_checkFsmForReady() != Fapi_Status_FsmReady){}	    oReturnCheck = Fapi_doBlankCheck((uint32 *)address, Sector2KB_u32length,&oFlashStatusWord);	    if(oReturnCheck != Fapi_Status_Success)	    {	        Example_Error(oReturnCheck);	    }	}}void	ProgramBootFlag(uint32 u32IndexAddr, uint32 u16Len){    uint32 u32Index = 0;    uint16 i = 0;    Fapi_StatusType  oReturnCheck;    Fapi_FlashStatusWordType  oFlashStatusWord;		oReturnCheck = Fapi_issueAsyncCommand(Fapi_ClearMore);    //    // Wait until FSM is done with erase sector operation    //    while (Fapi_checkFsmForReady() != Fapi_Status_FsmReady){}    if(oReturnCheck != Fapi_Status_Success)    {        //        // Check Flash API documentation for possible errors        //        Example_Error(oReturnCheck);    }    for(i=0, u32Index = u32IndexAddr; (u32Index < (u32IndexAddr + u16Len)); i+= 8, u32Index+= 8)    {		oReturnCheck = Fapi_issueProgrammingCommand((uint32 *)u32Index,BootFlag + i,		                                   8, 0, 0, Fapi_AutoEccGeneration);		while(Fapi_checkFsmForReady() == Fapi_Status_FsmBusy);		if(oReturnCheck != Fapi_Status_Success)		{		  Example_Error(oReturnCheck);		}		oReturnCheck = Fapi_doVerify((uint32 *)u32Index,								   4, (uint32 *)(uint32)(BootFlag + i),								   &oFlashStatusWord);		if(oReturnCheck != Fapi_Status_Success)		{		  Example_Error(oReturnCheck);		}    }}void	ProgramBootData(uint32 u32IndexAddr, uint32 u16Led){    uint32 u32Index = 0;    uint16 i = 0;    Fapi_StatusType  oReturnCheck;    Fapi_FlashStatusWordType  oFlashStatusWord;    for(i=0, u32Index = u32IndexAddr; (u32Index < (u32IndexAddr + u16Led)); i+= 8, u32Index+= 8)    {		oReturnCheck = Fapi_issueProgrammingCommand((uint32 *)u32Index,BootData + i,		                                   8, 0, 0, Fapi_AutoEccGeneration);		while(Fapi_checkFsmForReady() == Fapi_Status_FsmBusy);		if(oReturnCheck != Fapi_Status_Success)		{		  Example_Error(oReturnCheck);		}		oReturnCheck = Fapi_doVerify((uint32 *)u32Index,								   4, (uint32 *)(uint32)(BootData + i),								   &oFlashStatusWord);//      oReturnCheck = Fapi_doVerify((uint32 *)u32Index,//                                 4,BootData32 + (i/2),//                                 &oFlashStatusWord);		if(oReturnCheck != Fapi_Status_Success)		{		  Example_Error(oReturnCheck);		}    }    //Flash1EccRegs.ECC_ENABLE.bit.ENABLE = 0xA;}void	IAP_AppFlashProgram(void)			// IAP升级程序{	INT8U *pIAPFlagH;	INT8U *pIAPFlagL;		bIndex = 0;	while(1)	{		// Reset watch dog cnt		sIWDG_SysCtl_serviceWatchdog();				// Get the first byte which indicates the length of the data block		bRxIndex = 0;		IAP_UartRecv();		while((bRxBuff[0] < 5) || (bRxBuff[0] > cRX_BUFF_LEN_MAX))		{			bRxIndex = 0;			IAP_UartRecv(); 			continue;		}		// if((bRxBuff[0] < 5) || (bRxBuff[0] > cRX_BUFF_LEN_MAX))		// {		// 	bRxIndex = 0;		// 	IAP_UartRecv(); 		// 	continue;		// }		// Get the rest data and store in the buffer		bRxIndex = 1;		bWatchDog = 0;		while(bRxIndex < bRxBuff[0])		{			IAP_UartRecv();			if(++bRxIndex >= cRX_BUFF_LEN_MAX)			{				break;			}		}				//mCHGLEDOn;		//mPWRLEDOn;		GpioDataRegs.GPATOGGLE.bit.GPIO27 = 1;				if(bRxIndex >= 5)		{			bXorChkTemp = 0;			bXorChk = 0xFF;						bRxIndex -= 1;			dwFlashAddr = (INT32U)((INT16U)bRxBuff[2] * 256 + bRxBuff[3]);			dwFlashAddr += dwFlashAddrOffset;			for(bIndex = 0; bIndex < bRxIndex; bIndex++)			{				bXorChkTemp ^= bRxBuff[bIndex];			}			bXorChk = bRxBuff[bIndex];			bRxIndex += 1;		}		else		{			bXorChkTemp = 0xFF;			bXorChk = 0;		}				IAP_DelayMs(bTxDelay);		if(bXorChk == bXorChkTemp)		{			if((bRxIndex == 8) && (bRxBuff[4] == 'R')\				&& (bRxBuff[5] == 'O') && (bRxBuff[6] == 'A'))			{				IAP_UartSend('A');				IAP_UartSend((dwFlashAddrP >> 24) & 0XFF);				IAP_UartSend((dwFlashAddrP >> 16) & 0XFF);				IAP_UartSend((dwFlashAddrP >> 8)  & 0XFF);				IAP_UartSend((dwFlashAddrP) & 0XFF);				}			else if((bRxIndex == 12) && (bRxBuff[4] == 'C')\				&& (bRxBuff[5] == 'R') && (bRxBuff[6] == 'C'))			{				IAP_DelayMs(100);				dwIAPCRCData = (((INT32U)bRxBuff[7] << 24) + ((INT32U)bRxBuff[8] << 16) + \								((INT16U)bRxBuff[9] << 8)   + bRxBuff[10]);				dwFlashCRCData = sdwFlashCrc32(((INT16U *)FLASH_APP_ADDR_START), (FLASH_APP_ADDR_END - FLASH_APP_ADDR_START + 1));				if(dwIAPCRCData == dwFlashCRCData)				{					IAP_UartSend('A');				}				else				{					IAP_UartSend('N');				}			}			else if((bRxIndex == 10) && (bRxBuff[4] == 'E')\				&& (bRxBuff[5] == 'O') && (bRxBuff[6] == 'A'))			{				dwFlashAddrOffset = (INT32U)((INT16U)bRxBuff[7] * 256 + bRxBuff[8]) << 16;				if((dwFlashAddrOffset >= FLASH_ADDR_START) && (dwFlashAddrOffset <= FLASH_ADDR_END))				{					IAP_UartSend('A');				}				else				{					IAP_UartSend('N');				}			}			else if((bRxIndex == 8) && (bRxBuff[4] == 'E')\				&& (bRxBuff[5] == 'O') && (bRxBuff[6] == 'F'))			{				pIAPFlagH = (INT8U *)FLASH_APP_ADDR_START;				pIAPFlagL = (INT8U *)(FLASH_APP_ADDR_START + 1);					if((*pIAPFlagH == 0XFFFF) && (*pIAPFlagL == 0XFFFF))				{					pIAPFlagH = (INT8U *)FLASH_APP_BOOT_ADDR;					pIAPFlagL = (INT8U *)(FLASH_APP_BOOT_ADDR + 1);					if((*pIAPFlagH == 0XFFFF) && (*pIAPFlagL == 0XFFFF))					{						ProgramBootFlag(FLASH_APP_ADDR_START, 4);					}				}				if((*pIAPFlagH != 0XFFFF) && (*pIAPFlagL != 0XFFFF))				{					IAP_UartSend('A');					IAP_UartSend('\r');					//wakeCount = 200;					while(1);					//sIapFlgLook();				}				else				{					IAP_UartSend('N');				}			}			else if((dwFlashAddr >= FLASH_FLG_ADDR_START) && (dwFlashAddr < FLASH_FLG_ADDR_END))				{																									if((bRxBuff[8] == 'F' && bRxBuff[9] == '5')	\				|| (bRxBuff[10] == 'P' && bRxBuff[11] == 'N') \				|| (bRxBuff[5] == 'H'))				{					//pIAPFlagH = (INT8U *)FLASH_APP_ADDR_START;					//pIAPFlagL = (INT8U *)(FLASH_APP_ADDR_START + 1);					BootFlag[0] = (((INT16U)bRxBuff[4] << 8) + bRxBuff[5]);					BootFlag[1] = (((INT16U)bRxBuff[6] << 8) + bRxBuff[7]);						//if((*pIAPFlagH == 0XFFFF) && (*pIAPFlagL == 0XFFFF))					{						//ProgramBootFlag(FLASH_FLG_ADDR_START,2);					}					IAP_UartSend('A');				}				else				{					IAP_UartSend('N');				}			}			else if((dwFlashAddr >= FLASH_APP_ADDR_START) && (dwFlashAddr <= FLASH_APP_ADDR_END))			{				if((bRxBuff[1] % 2) == 0)	// 必须是 8 Byte 整数倍				{					bIndex = 4;	// 第四位是数据起始位					while(bRxBuff[1] > 0)					{						wFlashData1 = (((INT16U)bRxBuff[bIndex] << 8) + bRxBuff[bIndex + 1]);						BootData[uwFlashDataLen++] = wFlashData1;												if(bRxBuff[1] > 2)						{							bRxBuff[1] -= 2;							bIndex += 2;						}						else						{							if((dwFlashAddr < FLASH_FLG_ADDR_START) || (dwFlashAddr >= FLASH_FLG_ADDR_END))							{									dwFlashAddrP = dwFlashAddr;								ProgramBootData(dwFlashAddr, uwFlashDataLen);							}													bRxBuff[1] = 0;							for(; uwFlashDataLen > 0; uwFlashDataLen--)							{								BootData[uwFlashDataLen] = 0XFFFF;							}							//uwFlashDataLen = 0;						}					}										IAP_UartSend('A');				}				else				{					IAP_UartSend('N');				}			}			else			{				IAP_UartSend('N');			}		}		else		{			IAP_UartSend('N');		}				IAP_UartSend('\r');				mCHGLEDOff;		mPWRLEDOff;				IAP_DelayMs(bResDelay);	}}// C2000:FLASH数据按字  读取,按字节计算CRC32值// ARM:  FLASH数据按字节读取,按字节计算CRC32值// CRC32校验范围:整个APP区段数据(如果有部分地址因为特殊原因不校验,使用0xFF数据补上并计算)INT32U address1 = 0;static INT32U sdwFlashCrc32(const INT16U *buf, INT32U size){	INT32U i, crc, address;	INT8U Val1, Val2;		crc = 0xFFFFFFFF;	for(i = 0; i < size; i++)	{		// 需注意C2000是小端格式还是大端格式		// IAP程序中,此时BOOT标志还未写入,所以计算时直接按照BOOT标志计算		address = (INT32U)buf;		if((address == FLASH_APP_ADDR_START))	// 起始跳转指令		{			Val1 = ((BootFlag[0] >> 8) & 0xFF);			Val2 = (BootFlag[0] & 0xFF);		}		else if(address == (FLASH_APP_ADDR_START + 1))		{			Val1 = ((BootFlag[1] >> 8) & 0xff);			Val2 = (BootFlag[1] & 0xFF);		}		else if(address == FLASH_APP_BOOT_ADDR)	// BOOT标志		{			Val1 = 0x46;			Val2 = 0x35;		}		else if(address == (FLASH_APP_BOOT_ADDR + 1))		{			Val1 = 0x50;			Val2 = 0x4E;		}		else // ????Flash????		{			Val1 = (*buf) >> 8;			Val2 = (*buf) & 0xFF;		}		crc = crc32tab[(crc ^ Val1) & 0xFF] ^ (crc >> 8);		crc = crc32tab[(crc ^ Val2) & 0xFF] ^ (crc >> 8);		buf++;	}		return crc ^ 0xFFFFFFFF;}void	sIWDG_SysCtl_serviceWatchdog(void){	SysCtl_serviceWatchdog();	wakeCount = 0;}void	IAP_DelayMs(INT16U ms){	INT16U	yyy;	INT16U	xxx;		for(yyy = 0; yyy < ms; yyy++)	{		for(xxx = 0; xxx < 10000; xxx++)	// for 64Mhz--2660		{			asm("    NOP");		}	}}void	IAP_UartSend(INT8U bData){	if(dwUartRegs == BOOT_SCI_A)	{		while (SciaRegs.SCIFFTX.bit.TXFFST != 0)	    {				    }	    SciaRegs.SCITXBUF.all = bData;    }	else if(dwUartRegs == BOOT_SCI_B) 	{		while (ScibRegs.SCIFFTX.bit.TXFFST != 0)	    {				    }	    ScibRegs.SCITXBUF.all = bData;    }	else if(dwUartRegs == BOOT_SCI_C) 	{		while (ScicRegs.SCIFFTX.bit.TXFFST != 0)	    {				    }	    ScicRegs.SCITXBUF.all = bData;    }}void	IAP_UartRecv(void){	INT8U bRXFFSTData = 0;		if(dwUartRegs == BOOT_SCI_A)		{		bRXFFSTData = SciaRegs.SCIFFRX.bit.RXFFST;	}	else if (dwUartRegs == BOOT_SCI_B)	{		bRXFFSTData = ScibRegs.SCIFFRX.bit.RXFFST;	}	else if (dwUartRegs == BOOT_SCI_C)    {        bRXFFSTData = ScicRegs.SCIFFRX.bit.RXFFST;    }	while(bRXFFSTData == 0)	{		if(bWatchDog == 1)		{			sIWDG_SysCtl_serviceWatchdog();		}		if(bCommType == 0)		{			if(dwUartRegs == BOOT_SCI_A)			{				dwUartRegs = BOOT_SCI_B;			}			else if(dwUartRegs == BOOT_SCI_B)			{				dwUartRegs = BOOT_SCI_C;			}			else			{				dwUartRegs = BOOT_SCI_A;			}			}	 	if(dwUartRegs == BOOT_SCI_A)			{			bRXFFSTData = SciaRegs.SCIFFRX.bit.RXFFST;		}		else if	(dwUartRegs == BOOT_SCI_B)		{			bRXFFSTData = ScibRegs.SCIFFRX.bit.RXFFST;		}		else if (dwUartRegs == BOOT_SCI_C)        {            bRXFFSTData = ScicRegs.SCIFFRX.bit.RXFFST;        }	}	if(dwUartRegs == BOOT_SCI_A)	{		bRxBuff[bRxIndex] = SciaRegs.SCIRXBUF.bit.SAR;	}	else if (dwUartRegs == BOOT_SCI_B)	{ 		bRxBuff[bRxIndex] = ScibRegs.SCIRXBUF.bit.SAR;	}	else if (dwUartRegs == BOOT_SCI_C)    {        bRxBuff[bRxIndex] = ScicRegs.SCIRXBUF.bit.SAR;    }	if((bCommType == 0) && (bRxBuff[bRxIndex] == 'F'))	{		bCommType = 4;	}	else if(bCommType == 4)	{ 		if(bRxBuff[bRxIndex] == '\r')		{			if((bRxBuff[0] == 'F') && (bRxBuff[1] == '5') \				&& (bRxBuff[2] == 'P') && (bRxBuff[3] == 'N') \				&& (bRxBuff[6] == '\r'))			{								if((bRxBuff[4]=='0' && bRxBuff[5]=='1'))				{		 			if(dwUartRegs == BOOT_SCI_A)					{						bCommType = 1;					}					else if(dwUartRegs == BOOT_SCI_B)					{						bCommType = 2;					}					else					{						bCommType = 3;					}								}				else				{					bCommType = 0;					bRxIndex = 0;				}			}			else			{				bCommType = 0;				bRxIndex = 0;			}		}		else if(bRxIndex > 7)		{			bCommType = 0;			bRxIndex = 0;		}				if( bCommType == 0)		{			if(dwUartRegs == BOOT_SCI_A)			{				dwUartRegs = BOOT_SCI_B;			}			else if(dwUartRegs == BOOT_SCI_B)			{				dwUartRegs = BOOT_SCI_C;			}			else			{				dwUartRegs = BOOT_SCI_A;			}		}	}}